from pathlib import Path
import base64,json
R=Path(__file__).resolve().parents[2];O=R/'renders/dungeon_autotiles_v1';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={}
for e in m['themes']:
 data[e['id']]={**e,'images':{f:uri(O/'dtef'/e['id']/f) for f in e['files']}}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PMDO · laboratoire DTEF</title><style>*{box-sizing:border-box}body{margin:0;background:#171c24;color:#e8e8df;font:16px system-ui}header,main,footer{max-width:1320px;margin:auto;padding:24px}h1{font-size:30px;margin:10px 0}.tag{font-size:12px;letter-spacing:2px;color:#81c5b8}p{color:#bfc8cc;line-height:1.6}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}select,button{padding:11px;background:#2c3943;color:#fff;border:1px solid #577a83;border-radius:6px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px}canvas{width:100%;image-rendering:pixelated;background:repeating-conic-gradient(#252c33 0% 25%,#21272f 0% 50%) 50%/12px 12px}aside{padding:18px;background:#222d36;border-radius:8px}label{display:block;margin:14px 0}small{color:#b4c3c9}a{color:#a6e3d4}footer{border-top:1px solid #44565c}@media(max-width:800px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">PMDO / AUDINOWHO · FORMAT DTEF AUDITÉ</div><h1>Autotiles de donjon · forêt, eau, sakura</h1><p>Six prototypes sur les gabarits natifs : trois variantes chromatiques et trois essais de matières générées. Tuiles24×24,47 configurations, variantes et couches animées distinctes. Les séquences sources gardent leur cadence indépendante.</p></header><main><div class="controls"><select id="theme"></select><select id="mode"><option value="map">Carte de raccords animée</option><option value="sheet">Gabarit DTEF animé</option><option value="raw">PNG individuel / frame</option></select><select id="variant"><option value="0">Variante visuelle0</option><option value="1">Variante visuelle1</option><option value="2">Variante visuelle2</option></select><button id="play">Pause</button><button id="step">+1 frame logique</button><button id="save">Exporter vue PNG</button></div><div class="layout"><section><canvas id="view" width="576" height="432"></canvas><p id="status"></p><small>La carte teste des salles, couloirs, diagonales et bassins. La vue DTEF présente les blocs mur / secondaire / sol. Les cases vides et variantes absentes restent transparentes : ce n’est pas une erreur.</small></section><aside><b>Couches animées</b><div id="layers"></div><label>Frame logique : <input id="tick" type="number" min="0" value="0" style="width:110px"></label><label>PNG source <select id="file" style="width:100%"></select></label><a id="download">Télécharger ce PNG</a><p id="info"></p><small>Prévisualisation à60 frames logiques/s. Les durées DTEF sont exprimées en frames de jeu, pas en millisecondes. Pas d’import PMDO exécuté ici.</small></aside></div></main><footer><p><b>Vérifié :</b>47 masques,204 feuilles DTEF,2829 copies de tuiles/frames sources, alpha inchangé, bordures de4px protégées après recoloration, noms et cadences sans ambiguïté.</p><p>Sources : audinowho/DumpAsset (Apple Woods, Beach Cave) et RogueCollab/RogueEssence (importeur DTEF). Les matières inédites sont reprojetées dans les intérieurs des tuiles ; les géométries natives de raccord et les animations d’eau sont conservées. Les motifs générés ne sont pas des ressources canoniques originales.</p></footer><script>const DATA=__DATA__,c=document.getElementById('view'),ctx=c.getContext('2d'),themes=document.getElementById('theme'),files=document.getElementById('file');let entry,images={},enabled={},mode='map',variant=0,tick=0,playing=true,last=0;for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;themes.append(o)}themes.value='sakura_printemps';function im(src){const i=new Image();i.src=src;return i}function updateFile(){const a=document.getElementById('download');a.href=entry.images[files.value];a.download=entry.id+'_'+files.value}function setup(){entry=DATA[themes.value];images={};enabled={};tick=0;files.innerHTML='';for(const f of entry.files){images[f]=im(entry.images[f]);const o=document.createElement('option');o.value=f;o.textContent=f;files.append(o)}files.value='tileset_0.png';updateFile();const l=document.getElementById('layers');l.innerHTML='';for(const [key,s]of Object.entries(entry.animation_layers)){enabled[key]=true;const row=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.onchange=()=>enabled[key]=ch.checked;row.append(ch,document.createTextNode('V'+key.split(':')[0]+' · couche'+key.split(':')[1]+' : '+s.count+' frames × '+s.duration));l.append(row)}document.getElementById('info').textContent=entry.kind+' · source '+entry.source;document.getElementById('status').textContent=entry.title+' · '+entry.files.length+' feuilles PNG, hors échantillons de matière'}themes.onchange=setup;files.onchange=updateFile;document.getElementById('mode').onchange=e=>mode=e.target.value;document.getElementById('variant').onchange=e=>variant=+e.target.value;document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Lecture'};document.getElementById('step').onclick=()=>{playing=false;tick=Math.floor(tick)+1;document.getElementById('play').textContent='Lecture'};document.getElementById('tick').onchange=e=>{tick=Math.max(0,+e.target.value||0);playing=false;document.getElementById('play').textContent='Lecture'};document.getElementById('save').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL();a.download=entry.id+'_'+mode+'.png';a.click()};function draw(name,sx,sy,x,y){const i=images[name];if(!i||!i.complete||!i.naturalWidth)return;if(sx===undefined)ctx.drawImage(i,0,0);else ctx.drawImage(i,sx,sy,24,24,x,y,24,24)}function anim(v,sx,sy,x,y){for(const [key,s]of Object.entries(entry.animation_layers)){const [av,li]=key.split(':').map(Number);if(av!==v||!enabled[key])continue;const f=Math.floor(tick/s.duration)%s.count;draw('tileset_'+v+'_frame'+li+'_'+f+'.'+s.duration+'.png',sx,sy,x,y)}}function render(now){if(last&&playing)tick+=Math.min(now-last,250)*.06;last=now;const w=mode==='map'?576:432,h=mode==='map'?432:192;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(mode==='raw')draw(files.value);else if(mode==='sheet'){draw('tileset_'+variant+'.png');anim(variant)}else for(const [x,y,sx,sy,v]of entry.demo_tiles){draw('tileset_'+v+'.png',sx,sy,x,y);anim(v,sx,sy,x,y)}document.getElementById('tick').value=Math.floor(tick);requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R/'apercu_dungeon_autotiles_v1.html').write_text(h.replace('__DATA__',json.dumps(data)),encoding='utf8')
